   return  { queryKey, queryFn, enabled: tid !== null && tid !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof listPendingMentions>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
